import apiClient from './apiClient';

export const getAllEntries = async (username, sort = null) => {
  // Ensure we're using the correct path format for your backend
  let url = `/user/${username}/entry/getAll`;
  
  if (sort) {
    url += `?sort=${sort}`;
  }
  
  try {
    console.log('Making request to:', url); // Debug log
    const response = await apiClient.get(url);
    console.log('Response:', response.data); // Debug log
    return response.data;
  } catch (error) {
    console.error('Error fetching entries:', error.response ? error.response.data : error.message);
    throw error;
  }
};

export const getFilteredEntries = async (username, filters = {}) => {
  const { type, search, sortBy, sortOrder } = filters;
  let queryParams = [];
  
  if (type) queryParams.push(`type=${type}`);
  if (search) queryParams.push(`search=${search}`);
  if (sortBy) queryParams.push(`sort_by=${sortBy}`);
  if (sortOrder) queryParams.push(`sort_order=${sortOrder}`);
  
  const queryString = queryParams.length > 0 ? `?${queryParams.join('&')}` : '';
  const response = await apiClient.get(`/user/${username}/entry/getFiltered${queryString}`);
  
  return response.data;
};

export const createEntry = async (username, entryData) => {
  const response = await apiClient.post(`/user/${username}/entry/addNew`, entryData);
  return response.data;
};

export const updateEntry = async (username, entryId, entryData) => {
  const response = await apiClient.put(`/user/${username}/entry/${entryId}/edit`, entryData);
  return response.data;
};

export const deleteEntry = async (username, entryId) => {
  const response = await apiClient.delete(`/user/${username}/entry/${entryId}`);
  return response.data;
};

export const getSummary = async (username) => {
  const response = await apiClient.get(`/user/${username}/entry/summary`);
  return response.data;
};
